-- Flashcard top-up: Economics|Edexcel B|alevel — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/economics-edexcel-b-alevel.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is opportunity cost?', 'The value of the next best alternative given up when making a choice.', 1),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is a PPF and what does a point outside it show?', 'A curve showing the maximum combinations of two goods an economy can produce; a point outside is currently unattainable.', 2),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is the role of enterprise in the economy?', 'Entrepreneurs spot opportunities, organise resources and take risks, driving innovation, competition and growth.', 3),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is a mass market versus a niche market?', 'Mass market: large, general market with standardised products. Niche market: small, specialised segment with specific needs.', 4),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is market segmentation?', 'Dividing a market into groups of consumers with similar characteristics, e.g. age, income, location or lifestyle.', 5),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is brand loyalty and why does it matter?', 'Consumers repeatedly buy the same brand, which makes demand more price-inelastic and gives the firm pricing power.', 6),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is the difference between a normal and an inferior good?', 'Demand for a normal good rises as income rises (YED > 0); demand for an inferior good falls as income rises (YED < 0).', 7),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is the impact of social media on consumer behaviour?', 'It spreads information and reviews quickly, influences tastes through influencers, and enables targeted advertising.', 8),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What are the factors that shift the demand curve?', 'Income, tastes, prices of substitutes and complements, advertising, population and expectations.', 9),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is XED and what does a positive value show?', 'Cross elasticity of demand measures the response of demand for one good to a change in another''s price; a positive value shows substitutes.', 10),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is a social enterprise?', 'A business with social or environmental aims that reinvests profits to achieve those aims.', 11),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is a stakeholder?', 'Any individual or group affected by or with an interest in a business, e.g. employees, customers, shareholders and the local community.', 12),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What is quantitative and qualitative market research?', 'Quantitative produces numerical data (surveys, sales figures); qualitative explores opinions and motivations (focus groups, interviews).', 13),
  ('Economics', 'Edexcel B', 'alevel', '1.1', 'Scarcity, Enterprise, Markets & Consumers', 'What are the benefits of sampling in market research?', 'It is cheaper and quicker than surveying the whole population, although it may be biased or unrepresentative.', 14),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a business plan?', 'A document setting out a firm''s objectives, strategies, market analysis and financial forecasts, often used to raise finance.', 1),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What are sources of finance for a new business?', 'Personal savings, family and friends, bank loans, overdrafts, venture capital, crowdfunding and business angels.', 2),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a bank overdraft?', 'Short-term flexible borrowing up to an agreed limit on a current account; it is expensive if used long-term.', 3),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is crowdfunding?', 'Raising finance from many individuals, usually online, in return for rewards or equity.', 4),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is venture capital?', 'Finance provided to small, high-risk businesses by investors in return for equity and some control.', 5),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a sole trader?', 'A business owned by one person with unlimited liability, full control and keeping all profits.', 6),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a private limited company?', 'A company owned by shareholders with limited liability, whose shares cannot be sold to the public (Ltd).', 7),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a public limited company?', 'A company whose shares can be traded on the stock exchange, able to raise large amounts of capital (plc).', 8),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is the break-even point?', 'The level of output where total revenue equals total costs, so there is neither profit nor loss.', 9),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is contribution per unit?', 'Selling price minus variable cost per unit, which contributes towards fixed costs and profit.', 10),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is a cash-flow forecast?', 'A prediction of the cash inflows and outflows of a business over a period, used to identify cash shortages.', 11),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What causes business failure?', 'Poor cash flow, lack of demand, poor management, strong competition, and external shocks.', 12),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is the gross profit margin?', 'Gross profit ÷ revenue × 100.', 13),
  ('Economics', 'Edexcel B', 'alevel', '1.2', 'Credit, Market Failure, Costs & Profit', 'What is the operating profit margin?', 'Operating profit ÷ revenue × 100.', 14),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is competitiveness?', 'The ability of a firm or country to sell goods and services in domestic and international markets at a profit.', 1),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What factors determine international competitiveness?', 'Productivity, wage costs, exchange rates, inflation, taxes, regulation, and non-price factors like quality.', 2),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is the difference between labour and capital productivity?', 'Labour productivity is output per worker (or hour); capital productivity is output per unit of capital.', 3),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'How can productivity be increased?', 'Training, investment in new technology, better management, lean production and incentives.', 4),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is just-in-time production?', 'Holding minimal stock and receiving inputs only when needed, reducing storage costs but increasing supply chain risk.', 5),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is kaizen?', 'Continuous improvement through small, incremental changes suggested by workers.', 6),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is quality assurance?', 'Building quality into every stage of production to prevent defects, rather than inspecting at the end.', 7),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is total quality management?', 'A culture where every worker is responsible for quality throughout the organisation.', 8),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is the effect of a stronger pound on UK firms?', 'Exports become less competitive and imports cheaper, which hurts exporters but reduces the cost of imported raw materials.', 9),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is a recession?', 'Two consecutive quarters of negative economic growth.', 10),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is the impact of recession on firms?', 'Falling demand, lower profits, redundancies, and possible business failure, especially for luxury goods.', 11),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is inflation''s effect on business costs?', 'Higher raw material and wage costs, uncertainty for planning, and reduced international competitiveness.', 12),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is economic growth''s benefit to business?', 'Higher consumer incomes and demand, more investment opportunities, and higher profits.', 13),
  ('Economics', 'Edexcel B', 'alevel', '2.1', 'Competitiveness, Productivity & Economic Performance', 'What is a dynamic market?', 'A market that changes rapidly due to innovation, changing tastes, or new competitors.', 14),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is an expansionary monetary policy?', 'Lowering interest rates or using QE to increase aggregate demand.', 1),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is a contractionary fiscal policy?', 'Reducing government spending or raising taxes to reduce aggregate demand.', 2),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the effect of a rise in interest rates on firms?', 'Higher borrowing costs, lower consumer spending on credit, and a stronger pound hurting exporters.', 3),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'How does monetary policy affect exchange rates?', 'Higher interest rates attract hot money, increasing demand for the currency and causing appreciation.', 4),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the government''s budget?', 'The annual statement of planned government spending and tax revenue.', 5),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What are the main areas of UK government spending?', 'Social protection (welfare and pensions), health, education, debt interest and defence.', 6),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What are the main UK taxes?', 'Income tax, National Insurance, VAT, and corporation tax.', 7),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the impact of a rise in corporation tax on firms?', 'Lower post-tax profits, reduced investment, and less attractive for foreign firms.', 8),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the impact of a rise in VAT?', 'Higher prices, reduced consumer spending, and a regressive impact on lower incomes.', 9),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the impact of government infrastructure spending?', 'Increases AD in the short run and productive capacity in the long run, benefiting firms through lower costs.', 10),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What are the limitations of fiscal policy?', 'Time lags, crowding out, and political pressures; budget deficits and debt constrain its use.', 11),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What are the effects of supply-side policies on firms?', 'Lower costs, a more skilled workforce, more flexible labour markets and greater competition.', 12),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the difference between demand-side and supply-side policies'' effect on the price level?', 'Demand-side expansion can raise prices; supply-side policies can increase output while reducing inflationary pressure.', 13),
  ('Economics', 'Edexcel B', 'alevel', '2.2', 'Macroeconomic Policy', 'What is the Office for Budget Responsibility?', 'An independent body that produces economic forecasts and assesses the government''s fiscal plans.', 14),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What are the drivers of global trade?', 'Reductions in transport costs, trade liberalisation, improvements in ICT, and the growth of MNCs.', 1),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is comparative advantage?', 'A country can produce a good at a lower opportunity cost than another country.', 2),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is a tariff?', 'A tax on imported goods, raising their price and protecting domestic producers.', 3),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is a quota?', 'A limit on the quantity of a good that can be imported.', 4),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is protectionism''s cost to consumers?', 'Higher prices, less choice, and lower quality, as well as inefficiency among protected domestic firms.', 5),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is a trading bloc?', 'A group of countries agreeing to reduce or remove trade barriers between them, e.g. the EU or ASEAN.', 6),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is the impact of trading blocs on non-members?', 'Trade diversion and reduced access to markets, as members trade more with each other.', 7),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is the difference between an emerging economy and a developed economy?', 'Emerging economies have rapid growth and industrialisation (e.g. India); developed economies have high incomes and mature industries.', 8),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What factors attract firms to a new international market?', 'Market size and growth, low costs, skilled labour, political stability and infrastructure.', 9),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is offshoring?', 'Moving production or services abroad to take advantage of lower costs.', 10),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is reshoring?', 'Bringing production back to the home country, e.g. due to quality concerns or rising overseas costs.', 11),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is glocalisation?', 'Adapting global products to suit local tastes and cultures.', 12),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What are the ethical issues facing MNCs?', 'Low wages, poor working conditions, environmental damage, and tax avoidance.', 13),
  ('Economics', 'Edexcel B', 'alevel', '3.1', 'Globalisation, Trade & Global Business', 'What is transfer pricing?', 'The prices MNCs charge for transactions between their own subsidiaries in different countries, which can be used to shift profits to low-tax countries.', 14),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is labour market flexibility?', 'The ability of the labour market to respond quickly to changes in demand, through flexible hours, contracts and wages.', 1),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the brain drain?', 'Skilled workers emigrating from developing countries, reducing their human capital.', 2),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What are remittances?', 'Money sent home by migrant workers to their families, an important source of income in some developing countries.', 3),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the impact of skilled migration on the host country?', 'It fills skills gaps, increases output and tax revenue, but may put pressure on public services.', 4),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the national minimum wage?', 'A legal minimum hourly wage that employers must pay.', 5),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the living wage?', 'A wage based on the cost of living, which is voluntary and higher than the legal minimum.', 6),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What are the causes of wealth inequality?', 'Inheritance, differences in savings, house prices, and returns on assets.', 7),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is redistribution?', 'Government transfer of income and wealth from richer to poorer households through taxes and benefits.', 8),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is a progressive tax?', 'A tax where higher-income earners pay a larger proportion of their income, e.g. UK income tax.', 9),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What are the disincentive effects of high taxes?', 'They may reduce incentives to work, invest or take risks, and encourage tax avoidance.', 10),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What are the problems with means-tested benefits?', 'Complexity, stigma, low take-up, and the poverty trap.', 11),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the role of the state in providing education?', 'Improving human capital and social mobility, and reducing inequality of opportunity.', 12),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'What is the impact of technology on inequality?', 'It increases demand for highly skilled workers, widening the wage gap with low-skilled workers.', 13),
  ('Economics', 'Edexcel B', 'alevel', '3.2', 'Global Labour Markets, Inequality & Redistribution', 'How does inequality affect business?', 'Lower demand from poorer groups, social unrest, and luxury markets growing while mass markets shrink.', 14),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is market concentration?', 'The degree to which a market is dominated by a small number of large firms.', 1),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What are the barriers to entry in a market?', 'Economies of scale, high capital costs, brand loyalty, patents, legal barriers and control of supply.', 2),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is a sunk cost as a barrier to entry?', 'A cost that can''t be recovered when leaving the market, which deters entry.', 3),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is supernormal profit?', 'Profit above the level needed to keep a firm in the industry (above normal profit).', 4),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is price competition?', 'Competing on price to attract customers, such as discounting or price-matching.', 5),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is the impact of market power on consumers?', 'Higher prices, less choice and reduced innovation, although economies of scale may lower costs.', 6),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is the impact of market power on suppliers?', 'Firms with monopsony power can force down prices paid to suppliers.', 7),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is a merger control?', 'The CMA can block or impose conditions on mergers that would substantially lessen competition.', 8),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is a cartel?', 'A group of firms that agree to fix prices or output; this is illegal in the UK.', 9),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is price fixing?', 'Firms colluding to agree prices rather than competing, which harms consumers.', 10),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is predatory pricing?', 'Setting prices below cost to eliminate rivals, then raising prices later.', 11),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is the Competition and Markets Authority?', 'The UK body that promotes competition by investigating mergers, markets and anti-competitive behaviour.', 12),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is price capping?', 'A regulator limits the price a firm can charge, e.g. RPI − X for utilities.', 13),
  ('Economics', 'Edexcel B', 'alevel', '4.1', 'Competition & Market Power', 'What is nationalisation?', 'Bringing a private firm or industry under government ownership.', 14),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is market failure?', 'When the free market fails to allocate resources efficiently, leading to a loss of economic welfare.', 1),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is an external cost?', 'A cost suffered by third parties not involved in a transaction, e.g. pollution.', 2),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is a positive externality of consumption?', 'A benefit to third parties from consumption, e.g. vaccinations reducing the spread of disease.', 3),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is the tragedy of the commons?', 'Overuse of common resources that are rival but non-excludable, e.g. overfishing.', 4),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is government intervention to correct market failure?', 'Taxes, subsidies, regulation, state provision, tradeable permits, and information provision.', 5),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is the impact of a carbon tax on firms?', 'Higher costs for polluting firms, which may encourage cleaner technology, but can reduce competitiveness.', 6),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is the impact of regulation on firms?', 'Higher compliance costs, but it can create a level playing field and protect consumers.', 7),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is the difference between risk and uncertainty?', 'Risk can be measured and assigned a probability; uncertainty cannot be predicted.', 8),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is the role of the central bank in financial markets?', 'Setting interest rates, acting as lender of last resort, and regulating the banking system.', 9),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is moral hazard in banking?', 'Banks take excessive risks because they believe they will be bailed out if they fail.', 10),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is speculation?', 'Buying assets in the expectation of making a profit from future price changes.', 11),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is a financial bubble?', 'Asset prices rise far above their underlying value due to speculation, then crash.', 12),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What caused the 2008 financial crisis?', 'Subprime mortgage lending, securitisation, excessive leverage, and a housing bubble collapse.', 13),
  ('Economics', 'Edexcel B', 'alevel', '4.2', 'Market Failure, Policy Impact & Financial Risk', 'What is financial regulation''s aim?', 'To maintain the stability of the financial system and protect consumers.', 14)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Economics' AND exam_board = 'Edexcel B' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
